#!/usr/bin/env bash
# generate-env.sh — Produce a production-ready deploy/env/.env from .env.example.
#
# All CHANGE_ME placeholders are replaced with cryptographically strong secrets
# generated by openssl. The operator's domain and SMTP details are injected
# from positional arguments or environment variables.
#
# The generated file is written to deploy/env/.env (gitignored). It is NEVER
# committed. Re-running the script overwrites the previous .env — back it up
# first if you need to keep old secrets.
#
# Usage:
#   sudo bash deploy/env/generate-env.sh <domain> [operator-email]
#
# Or via environment variables:
#   LUMO_DOMAIN=api.example.com LUMO_OPERATOR_EMAIL=you@example.com \
#     sudo bash deploy/env/generate-env.sh
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
EXAMPLE="$ROOT/deploy/env/.env.example"
OUTPUT="$ROOT/deploy/env/.env"

# ---- resolve inputs ---------------------------------------------------------
DOMAIN="${1:-${LUMO_DOMAIN:-}}"
OPERATOR_EMAIL="${2:-${LUMO_OPERATOR_EMAIL:-}}"

if [ -z "$DOMAIN" ]; then
  echo "ERROR: domain is required." >&2
  echo "Usage: sudo bash deploy/env/generate-env.sh <domain> [operator-email]" >&2
  echo "   or: LUMO_DOMAIN=... LUMO_OPERATOR_EMAIL=... bash deploy/env/generate-env.sh" >&2
  exit 1
fi

if [ -z "$OPERATOR_EMAIL" ]; then
  echo "WARN: operator email not provided — CERTBOT_EMAIL will be blank."
  echo "WARN: Caddy will still obtain certs but Let's Encrypt cannot send expiry notices."
fi

# ---- prerequisites ----------------------------------------------------------
if [ ! -f "$EXAMPLE" ]; then
  echo "ERROR: $EXAMPLE not found. Run from the repository root." >&2
  exit 1
fi

if ! command -v openssl >/dev/null 2>&1; then
  echo "ERROR: openssl is required but not installed." >&2
  exit 1
fi

# ---- generate secrets -------------------------------------------------------
gen_b64() { openssl rand -base64 "$1" 2>/dev/null | tr -d '\n'; }
gen_hex() { openssl rand -hex "$1" 2>/dev/null | tr -d '\n'; }

POSTGRES_PASSWORD="$(gen_b64 32)"
JWT_SECRET="$(gen_b64 48)"
SECRET_KEY_BASE="$(gen_b64 48)"
VAULT_ENC_KEY="$(gen_hex 16)"          # exactly 32 hex chars = 32 char string
PG_META_CRYPTO_KEY="$(gen_b64 24)"

# Dashboard credentials
DASHBOARD_USERNAME="lumo-admin"
DASHBOARD_PASSWORD="$(gen_hex 16)"

# Studio / admin internal password (Supabase Studio requires letters+digits, not all numbers)
STUDIO_PASSWORD="$(gen_b64 16 | tr -dc 'A-Za-z0-9' | head -c 24)"

# Placeholder for asymmetric keys — operator must run upstream helper after sync
ANON_KEY=""
SERVICE_ROLE_KEY=""

echo "Generated secrets (will not be repeated — save them now if needed):" >&2
echo "  POSTGRES_PASSWORD    : [set]" >&2
echo "  JWT_SECRET           : [set]" >&2
echo "  SECRET_KEY_BASE      : [set]" >&2
echo "  VAULT_ENC_KEY        : [set]" >&2
echo "  PG_META_CRYPTO_KEY   : [set]" >&2
echo "  DASHBOARD_USERNAME   : $DASHBOARD_USERNAME" >&2
echo "  DASHBOARD_PASSWORD   : [set]" >&2

# ---- write the .env file ----------------------------------------------------
# We read .env.example line by line and substitute placeholders.
# For lines that are not secret placeholders, we pass them through unchanged.

tmp="$(mktemp)"
trap 'rm -f "$tmp"' EXIT

while IFS= read -r line || [ -n "$line" ]; do
  case "$line" in
    POSTGRES_PASSWORD=CHANGE_ME*)    echo "POSTGRES_PASSWORD=$POSTGRES_PASSWORD" ;;
    JWT_SECRET=CHANGE_ME*)            echo "JWT_SECRET=$JWT_SECRET" ;;
    SECRET_KEY_BASE=CHANGE_ME*)       echo "SECRET_KEY_BASE=$SECRET_KEY_BASE" ;;
    VAULT_ENC_KEY=CHANGE_ME*)         echo "VAULT_ENC_KEY=$VAULT_ENC_KEY" ;;
    PG_META_CRYPTO_KEY=CHANGE_ME*)    echo "PG_META_CRYPTO_KEY=$PG_META_CRYPTO_KEY" ;;
    DASHBOARD_USERNAME=CHANGE_ME*)    echo "DASHBOARD_USERNAME=$DASHBOARD_USERNAME" ;;
    DASHBOARD_PASSWORD=CHANGE_ME*)    echo "DASHBOARD_PASSWORD=$DASHBOARD_PASSWORD" ;;
    SUPABASE_PUBLIC_URL=*)            echo "SUPABASE_PUBLIC_URL=https://$DOMAIN" ;;
    API_EXTERNAL_URL=*)               echo "API_EXTERNAL_URL=https://$DOMAIN/auth/v1" ;;
    PROXY_DOMAIN=*)                   echo "PROXY_DOMAIN=$DOMAIN" ;;
    CERTBOT_EMAIL=*)                  echo "CERTBOT_EMAIL=$OPERATOR_EMAIL" ;;
    SMTP_ADMIN_EMAIL=CHANGE_ME*)      echo "SMTP_ADMIN_EMAIL=$OPERATOR_EMAIL" ;;
    *)
      # Pass through unchanged
      echo "$line"
      ;;
  esac
done < "$EXAMPLE" > "$tmp"

# Safety check: no CHANGE_ME should remain
if grep -q 'CHANGE_ME' "$tmp"; then
  REMAINING="$(grep -n 'CHANGE_ME' "$tmp" || true)"
  echo "ERROR: placeholders remain in generated .env:" >&2
  echo "$REMAINING" >&2
  echo "These likely need operator-supplied values (SMTP, backup destination)." >&2
  echo "The file has been written — edit deploy/env/.env manually to fill them." >&2
fi

mv "$tmp" "$OUTPUT"
chmod 600 "$OUTPUT"

echo "" >&2
echo "Written: $OUTPUT (mode 600, gitignored)" >&2
echo "" >&2
echo "Remaining manual steps:" >&2
echo "  1. Set SMTP_HOST, SMTP_PORT, SMTP_USER, SMTP_PASS for email auth" >&2
echo "  2. Set LUMO_BACKUP_DESTINATION and LUMO_BACKUP_ENCRYPTION_KEY" >&2
echo "  3. After sync-upstream.sh, run:" >&2
echo "       sh vendor/supabase-docker/utils/generate-keys.sh" >&2
echo "       sh vendor/supabase-docker/utils/add-new-auth-keys.sh" >&2
echo "     to generate ANON_KEY, SERVICE_ROLE_KEY, SUPABASE_PUBLISHABLE_KEY," >&2
echo "     SUPABASE_SECRET_KEY, JWT_KEYS, JWT_JWKS" >&2
echo "  4. Run: sh scripts/check-secrets.sh" >&2
